221	func runTrailListAllValidatedWithClient(ctx context.Context, w io.Writer, client *api.Client, opts trailListOptions) error {
222		statusFilters, err := validateTrailListOptions(opts)
223		if err != nil {
224			return err
225		}
226		return runTrailListAllWithClient(ctx, w, client, opts, statusFilters)
227	}
