229	func runTrailListAllWithClient(ctx context.Context, w io.Writer, client *api.Client, opts trailListOptions, statusFilters []trail.Status) error {
230		authorFilter := opts.Author
231		currentUserLogin := ""
232		if authorFilter == trailListAuthorMe {
233			login, err := fetchCurrentUserLogin(ctx, execRunner{})
234			if err != nil {
235				return err
236			}
237			currentUserLogin = login
238			authorFilter = login
239		}
240	
241		forge, owner, repo, err := resolveTrailRemote(ctx)
242		if err != nil {
243			return err
244		}
245	
246		// Filtering, sorting (updated_at desc), and truncation all happen
247		// server-side; the response carries the total match count so a capped
248		// page never reads as the total number of matches.
249		resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo)+trailListQuery(statusFilters, authorFilter, opts.Limit))
250		if err != nil {
251			return fmt.Errorf("failed to list trails: %w", err)
252		}
253		defer resp.Body.Close()
254		if err := checkTrailResponse(resp); err != nil {
255			return err
256		}
257	
258		var listResp api.TrailListResponse
259		if err := api.DecodeJSON(resp, &listResp); err != nil {
260			return fmt.Errorf("failed to decode trail list: %w", err)
261		}
262	
263		// Convert to metadata for display
264		trails := make([]*trail.Metadata, 0, len(listResp.Trails))
265		for i := range listResp.Trails {
266			trails = append(trails, listResp.Trails[i].ToMetadata())
267		}
268	
269		totalMatched := listResp.Total
270		if totalMatched < len(trails) {
271			// Older servers don't report a total; fall back to the page size.
272			totalMatched = len(trails)
273		}
274	
275		if opts.JSON {
276			enc := json.NewEncoder(w)
277			enc.SetIndent("", "  ")
278			if err := enc.Encode(trails); err != nil {
279				return fmt.Errorf("failed to encode JSON: %w", err)
280			}
281			return nil
282		}
283	
284		if len(trails) == 0 {
285			printTrailListEmpty(w, authorFilter, statusFilters)
286			return nil
287		}
288	
289		printTrailList(w, trails, trailListDisplayOptions{
290			RequestedAuthor: authorFilter,
291			CurrentUser:     currentUserLogin,
292			StatusFilters:   statusFilters,
293			TotalMatched:    totalMatched,
294		})
295	
296		if opts.Limit > trailListServerMaxLimit && totalMatched > len(trails) {
297			fmt.Fprintln(w)
298			fmt.Fprintf(w, "Note: --limit %d exceeds the server maximum of %d trails per request.\n", opts.Limit, trailListServerMaxLimit)
299		}
300	
301		return nil
302	}
