304	// trailListQuery builds the server-side filter query for the trail list
305	// endpoint. Empty statusFilters (--status any) omits the status param so the
306	// server returns all statuses; the limit is capped at the server maximum.
307	func trailListQuery(statusFilters []trail.Status, author string, limit int) string {
308		return trailListQueryWithOffset(statusFilters, author, limit, 0)
309	}
310	
311	func trailListQueryWithOffset(statusFilters []trail.Status, author string, limit, offset int) string {
312		q := url.Values{}
313		if len(statusFilters) > 0 {
314			parts := make([]string, len(statusFilters))
315			for i, status := range statusFilters {
316				parts[i] = string(status)
317			}
318			q.Set("status", strings.Join(parts, ","))
319		}
320		if author != "" {
321			q.Set("author", author)
322		}
323		if limit > trailListServerMaxLimit {
324			limit = trailListServerMaxLimit
325		}
326		q.Set("limit", strconv.Itoa(limit))
327		if offset > 0 {
328			q.Set("offset", strconv.Itoa(offset))
329		}
330		return "?" + q.Encode()
331	}
