333	// printTrailListEmpty renders the empty-state message. It names the active
334	// status filter so a bare `entire trail list` (which defaults to open)
335	// doesn't read as "this repo has no trails" when trails exist in other
336	// statuses. statusFilters is empty when the user passed --status any.
337	func printTrailListEmpty(w io.Writer, authorFilter string, statusFilters []trail.Status) {
338		desc := "No trails found"
339		if len(statusFilters) > 0 {
340			desc = fmt.Sprintf("No %s trails found", trailStatusListDisplay(statusFilters))
341		}
342		if authorFilter != "" {
343			desc += " for " + authorFilter
344		}
345		fmt.Fprintf(w, "%s.\n", desc)
346	
347		if len(statusFilters) > 0 {
348			fmt.Fprintln(w)
349			fmt.Fprintln(w, "Use --status any to see trails in other statuses.")
350		}
351	
352		fmt.Fprintln(w)
353		fmt.Fprintln(w, "Commands:")
354		fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
355		fmt.Fprintln(w, "  entire trail list     List recent trails")
356		fmt.Fprintln(w, "  entire trail update   Update trail metadata")
357	}
