359	func parseTrailStatusFilter(filter string) ([]trail.Status, error) {
360		if filter == "" || filter == trailListStatusAny {
361			return nil, nil
362		}
363	
364		parts := strings.Split(filter, ",")
365		statuses := make([]trail.Status, 0, len(parts))
366		seen := make(map[trail.Status]bool, len(parts))
367		for _, part := range parts {
368			name := strings.TrimSpace(part)
369			if name == "" {
370				return nil, fmt.Errorf("invalid status filter %q: empty status", filter)
371			}
372			status := trail.Status(name)
373			if !status.IsValid() {
374				return nil, fmt.Errorf("invalid status %q: valid values are %s", name, formatValidStatuses())
375			}
376			if seen[status] {
377				continue
378			}
379			seen[status] = true
380			statuses = append(statuses, status)
381		}
382		return statuses, nil
383	}
