385	// fetchCurrentUserLogin resolves --author me to a GitHub login via the local
386	// gh CLI. The runner is injectable so tests can stub gh without touching the
387	// process environment.
388	func fetchCurrentUserLogin(ctx context.Context, runner bootstrapRunner) (string, error) {
389		login, err := ghCurrentUser(ctx, runner)
390		if err != nil {
391			return "", fmt.Errorf("resolve --author %s via gh CLI: %w\nhint: pass --author <login> explicitly if gh is unavailable", trailListAuthorMe, err)
392		}
393		if login == "" {
394			return "", errors.New("resolve --author me: gh returned an empty login")
395		}
396		return login, nil
397	}
