399	type trailListDisplayOptions struct {
400		RequestedAuthor string
401		CurrentUser     string
402		StatusFilters   []trail.Status
403		// TotalMatched is the number of trails matching the filters server-side,
404		// before --limit truncation. Counts render as "shown/total" when they
405		// differ so a capped page doesn't read as the total number of matches.
406		TotalMatched int
407	}
