409	func printTrailList(w io.Writer, trails []*trail.Metadata, opts trailListDisplayOptions) {
410		showAuthor := opts.RequestedAuthor == ""
411		// Show the status column unless exactly one status is filtered — that
412		// status is already named in the header.
413		showStatus := len(opts.StatusFilters) != 1
414		printTrailListHeader(w, opts, len(trails))
415		fmt.Fprintln(w)
416		printTrailRows(w, trails, showAuthor, showStatus)
417	}
418	
419	func printTrailListHeader(w io.Writer, opts trailListDisplayOptions, count int) {
420		countStr := trailCountDisplay(count, opts.TotalMatched)
421		// The noun refers to the full match set, so pluralize by the total when
422		// the page is truncated ("1/2 trails", not "1/2 trail").
423		nounCount := count
424		if opts.TotalMatched > count {
425			nounCount = opts.TotalMatched
426		}
427		if opts.RequestedAuthor == "" {
428			if len(opts.StatusFilters) == 0 {
429				fmt.Fprintf(w, "  Recent %s · %s\n", pluralize("trail", nounCount), countStr)
430				return
431			}
432			fmt.Fprintf(w, "  %s · %s %s\n", trailStatusListTitle(opts.StatusFilters), countStr, pluralize("trail", nounCount))
433			return
434		}
435	
436		label := opts.RequestedAuthor
437		// When --author me resolves to the same login the server already returned
438		// for the trail, render "Your trails (login)" so identity drift between
439		// gh and Entire is visible at a glance.
440		if opts.CurrentUser != "" && strings.EqualFold(opts.RequestedAuthor, opts.CurrentUser) {
441			label = fmt.Sprintf("Your trails (%s)", opts.CurrentUser)
442		}
443		if len(opts.StatusFilters) == 0 {
444			fmt.Fprintf(w, "  %s · %s\n", label, countStr)
445			return
446		}
447		fmt.Fprintf(w, "  %s · %s %s\n", label, countStr, trailStatusListDisplay(opts.StatusFilters))
448	}
