450	func printTrailRows(w io.Writer, trails []*trail.Metadata, showAuthor, showStatus bool) {
451		// tabwriter aligns by display columns instead of bytes, so multi-byte
452		// branch names or logins don't throw off the table.
453		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
454		showPhase := trailListHasPhase(trails)
455		columns := []string{"NUM", "BRANCH", "TITLE"}
456		if showStatus {
457			columns = append(columns, "STATUS")
458		}
459		if showPhase {
460			columns = append(columns, "PHASE")
461		}
462		if showAuthor {
463			columns = append(columns, "AUTHOR")
464		}
465		columns = append(columns, "UPDATED")
466		fmt.Fprintln(tw, "  "+strings.Join(columns, "\t"))
467		for _, t := range trails {
468			number := "-"
469			if t.Number > 0 {
470				number = strconv.Itoa(t.Number)
471			}
472			title := truncateOneLine(t.Title, 60)
473			if title == "" {
474				title = "(untitled)"
475			}
476			fields := []string{number, t.Branch, title}
477			if showStatus {
478				fields = append(fields, trailStatusDisplay(t.Status))
479			}
480			if showPhase {
481				fields = append(fields, trailPhaseDisplay(t.Phase))
482			}
483			if showAuthor {
484				fields = append(fields, t.AuthorLogin())
485			}
486			fields = append(fields, timeAgo(t.UpdatedAt))
487			fmt.Fprintln(tw, "  "+strings.Join(fields, "\t"))
488		}
489		_ = tw.Flush()
490	}
491	
492	func trailListHasPhase(trails []*trail.Metadata) bool {
493		for _, t := range trails {
494			if t != nil && strings.TrimSpace(t.Phase) != "" {
495				return true
496			}
497		}
498		return false
499	}
500	
501	func trailPhaseDisplay(phase string) string {
502		phase = strings.TrimSpace(phase)
503		if phase == "" {
504			return "-"
505		}
506		return strings.ReplaceAll(phase, "_", " ")
507	}
508	
509	func trailStatusListDisplay(statuses []trail.Status) string {
510		parts := make([]string, len(statuses))
511		for i, status := range statuses {
512			parts[i] = trailStatusDisplay(status)
513		}
514		return strings.Join(parts, ", ")
515	}
516	
517	func trailStatusListTitle(statuses []trail.Status) string {
518		display := trailStatusListDisplay(statuses)
519		if display == "" {
520			return ""
521		}
522		return strings.ToUpper(display[:1]) + display[1:]
523	}
524	
525	func trailStatusDisplay(status trail.Status) string {
526		return strings.ReplaceAll(string(status), "_", " ")
527	}
528	
529	// trailCountDisplay renders a count as "shown/total" when --limit truncated
530	// the list, so a capped page doesn't read as the total number of matches.
531	func trailCountDisplay(shown, total int) string {
532		if total > shown {
533			return fmt.Sprintf("%d/%d", shown, total)
534		}
535		return strconv.Itoa(shown)
536	}
537	
538	func pluralize(s string, count int) string {
539		if count == 1 {
540			return s
541		}
542		return s + "s"
543	}
