568	//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
569	func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
570		ctx := cmd.Context()
571		w := cmd.OutOrStdout()
572		errW := cmd.ErrOrStderr()
573	
574		repo, err := strategy.OpenRepository(ctx)
575		if err != nil {
576			return fmt.Errorf("failed to open repository: %w", err)
577		}
578		defer repo.Close()
579	
580		// Determine base branch.
581		if base == "" {
582			base = strategy.GetDefaultBranchName(repo)
583			if base == "" {
584				base = defaultBaseBranch
585			}
586		}
587	
588		_, currentBranch, _ := isOnDefaultBranchRepo(repo) //nolint:errcheck // best-effort; reuse the open repo for the current branch name
589		interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
590	
591		if interactive {
592			// Interactive flow: title → body → branch (derived) → status.
593			if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
594				return handleFormCancellation(w, "Trail creation", err)
595			}
596		} else {
597			// Non-interactive: derive missing values from provided flags. With
598			// --branch omitted, use the checked-out branch (a feature branch); only
599			// slug a new branch from the title when the checked-out branch is the base.
600			branch = resolveCreateBranch(branch, currentBranch, base, title, cmd.Flags().Changed("title"))
601			if title == "" {
602				title = trail.HumanizeBranchName(branch)
603			}
604		}
605		title = strings.TrimSpace(title)
606		base = strings.TrimSpace(base)
607		branch = strings.TrimSpace(branch)
608		statusStr = strings.TrimSpace(statusStr)
609		if title == "" {
610			return errors.New("trail title is required")
611		}
612		if branch == "" {
613			return errors.New("branch name is required")
614		}
615		if statusStr == "" {
616			statusStr = string(trail.StatusDraft)
617		}
618		if status := trail.Status(statusStr); !status.IsValid() {
619			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
620		}
621	
622		needsCreation := branchNeedsCreation(repo, branch)
623	
624		client, err := NewAuthenticatedAPIClient(ctx, trailInsecureHTTP(cmd))
625		if err != nil {
626			return renderDataAPIAuthError(cmd.ErrOrStderr(), err)
627		}
628		forge, owner, repoName, err := resolveTrailRemote(ctx)
629		if err != nil {
630			return err
631		}
632	
633		localBranchCreated := false
634		remoteBranchPushed := false
635		if needsCreation {
636			if err := createBranch(repo, branch); err != nil {
637				return fmt.Errorf("failed to create branch %q: %w", branch, err)
638			}
639			localBranchCreated = true
640			fmt.Fprintf(w, "Created branch %s\n", branch)
641		} else if currentBranch != branch {
642			fmt.Fprintf(w, "Note: trail will be created for branch %q (not the current branch)\n", branch)
643		}
644	
645		if needsCreation {
646			// needsCreation is a local-only signal, so the branch may still exist on
647			// origin (e.g. a teammate pushed it and we never fetched). In that case the
648			// remote branch is not ours, and our push may merely fast-forward it; we
649			// must not delete it during cleanup. Only treat the remote branch as
650			// created-by-us when it did not already exist before our push.
651			existedOnOrigin, existErr := branchExistsOnOrigin(branch)
652			if existErr != nil {
653				// Be conservative: if we cannot tell, do not delete the remote branch.
654				fmt.Fprintf(errW, "Warning: could not check whether branch %s already exists on origin: %v\n", branch, existErr)
655				existedOnOrigin = true
656			}
657			if err := pushBranchToOrigin(branch); err != nil {
658				cleanupCreatedTrailBranch(repo, branch, localBranchCreated, false, errW)
659				return fmt.Errorf("failed to push branch %q: %w", branch, err)
660			}
661			remoteBranchPushed = !existedOnOrigin
662			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
663		}
664	
665		createReq := api.TrailCreateRequest{
666			Title:      title,
667			Body:       body,
668			BranchName: branch,
669			Base:       base,
670			Status:     statusStr,
671		}
672	
673		var createResp api.TrailCreateResponse
674		resp, err := client.Post(ctx, trailsBasePath(forge, owner, repoName), createReq)
675		if err != nil {
676			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
677			return fmt.Errorf("failed to create trail: %w", err)
678		}
679		defer resp.Body.Close()
680		if err := checkTrailResponse(resp); err != nil {
681			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
682			return err
683		}
684	
685		if err := api.DecodeJSON(resp, &createResp); err != nil {
686			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
687			return fmt.Errorf("failed to decode create response: %w", err)
688		}
689	
690		fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", createResp.Trail.Title, createResp.Trail.Branch, createResp.Trail.ID)
691	
692		if needsCreation && currentBranch != branch {
693			shouldCheckout := checkout
694			if !shouldCheckout && !cmd.Flags().Changed("checkout") {
695				// Interactive: ask whether to checkout
696				form := NewAccessibleForm(
697					huh.NewGroup(
698						huh.NewConfirm().
699							Title(fmt.Sprintf("Check out branch %s?", branch)).
700							Value(&shouldCheckout),
701					),
702				)
703				if formErr := form.Run(); formErr == nil && shouldCheckout {
704					checkout = true
705				}
706			}
707			if checkout {
708				if err := CheckoutBranch(ctx, branch); err != nil {
709					return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
710				}
711				fmt.Fprintf(w, "Switched to branch %s\n", branch)
712			}
713		}
714	
715		return nil
716	}
