763	func runTrailUpdate(ctx context.Context, w, errW io.Writer, insecureHTTP bool, inputs trailUpdateInputs) error {
764		return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, func(ctx context.Context, client *api.Client) error {
765			forge, owner, repoName, err := resolveTrailRemote(ctx)
766			if err != nil {
767				return err
768			}
769	
770			// Determine branch.
771			branch := inputs.Branch
772			if branch == "" {
773				branch, err = GetCurrentBranch(ctx)
774				if err != nil {
775					return fmt.Errorf("failed to determine current branch: %w", err)
776				}
777			}
778	
779			// Find the trail by branch.
780			found, err := findTrailByBranch(ctx, client, forge, owner, repoName, branch)
781			if err != nil {
782				return err
783			}
784			if found == nil {
785				return fmt.Errorf("no trail found for branch %q", branch)
786			}
787	
788			// Interactive mode when no update flags are provided.
789			statusStr := inputs.Status
790			title := inputs.Title
791			body := inputs.Body
792			noFlags := !inputs.StatusChanged && !inputs.TitleChanged && !inputs.BodyChanged && inputs.LabelAdd == nil && inputs.LabelRemove == nil
793			if noFlags {
794				metadata := found.ToMetadata()
795				// Build status options with current value as default.
796				var statusOptions []huh.Option[string]
797				for _, s := range trail.ValidStatuses() {
798					if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
799						continue
800					}
801					label := string(s)
802					if s == metadata.Status {
803						label += " (current)"
804					}
805					statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
806				}
807				statusStr = string(metadata.Status)
808				title = metadata.Title
809				body = metadata.Body
810	
811				form := NewAccessibleForm(
812					huh.NewGroup(
813						huh.NewSelect[string]().
814							Title("Status").
815							Options(statusOptions...).
816							Value(&statusStr),
817						huh.NewInput().
818							Title("Title").
819							Value(&title),
820						huh.NewText().
821							Title("Body").
822							Value(&body),
823					),
824				)
825				if formErr := form.Run(); formErr != nil {
826					return handleFormCancellation(w, "Trail update", formErr)
827				}
828				inputs.StatusChanged = true
829				inputs.TitleChanged = true
830				inputs.BodyChanged = true
831			}
832	
833			statusStr = strings.TrimSpace(statusStr)
834			title = strings.TrimSpace(title)
835			if err := validateTrailUpdateFields(trailUpdateInputs{
836				Status:        statusStr,
837				StatusChanged: inputs.StatusChanged,
838				Title:         title,
839				TitleChanged:  inputs.TitleChanged,
840			}); err != nil {
841				return err
842			}
843	
844			// Build update request with only changed fields.
845			updateReq := buildTrailUpdateRequest(found, trailUpdateInputs{
846				Status:        statusStr,
847				StatusChanged: inputs.StatusChanged,
848				Title:         title,
849				TitleChanged:  inputs.TitleChanged,
850				Body:          body,
851				BodyChanged:   inputs.BodyChanged,
852				LabelAdd:      inputs.LabelAdd,
853				LabelRemove:   inputs.LabelRemove,
854			})
855	
856			// The single-trail endpoint is keyed by trail number, not id; the server
857			// rejects an id here with "Invalid trail number format".
858			if found.Number <= 0 {
859				return fmt.Errorf("trail for branch %q has no number yet; cannot update", branch)
860			}
861			resp, err := client.Patch(ctx, trailNumberPath(forge, owner, repoName, found.Number), updateReq)
862			if err != nil {
863				return fmt.Errorf("failed to update trail: %w", err)
864			}
865			defer resp.Body.Close()
866			if err := checkTrailResponse(resp); err != nil {
867				return err
868			}
869	
870			var updateResp api.TrailUpdateResponse
871			if err := api.DecodeJSON(resp, &updateResp); err != nil {
872				return fmt.Errorf("failed to decode update response: %w", err)
873			}
874	
875			fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
876			return nil
877		})
878	}
