880	func validateTrailUpdateFields(inputs trailUpdateInputs) error {
881		if inputs.TitleChanged && strings.TrimSpace(inputs.Title) == "" {
882			return errors.New("trail title is required")
883		}
884		if inputs.StatusChanged {
885			status := trail.Status(strings.TrimSpace(inputs.Status))
886			if !status.IsValid() {
887				return fmt.Errorf("invalid status %q: valid values are %s", inputs.Status, formatValidStatuses())
888			}
889		}
890		return nil
891	}
