893	// buildTrailUpdateRequest constructs a PATCH request body from the current trail and the requested changes.
894	func buildTrailUpdateRequest(current *api.TrailResource, inputs trailUpdateInputs) api.TrailUpdateRequest {
895		var req api.TrailUpdateRequest
896	
897		if inputs.StatusChanged {
898			req.Status = &inputs.Status
899		}
900		if inputs.TitleChanged {
901			req.Title = &inputs.Title
902		}
903		if inputs.BodyChanged {
904			req.Body = &inputs.Body
905		}
906	
907		// Handle label changes: merge adds, remove removes.
908		if len(inputs.LabelAdd) > 0 || len(inputs.LabelRemove) > 0 {
909			labels := make([]string, 0, len(current.Labels)+len(inputs.LabelAdd))
910			labels = append(labels, current.Labels...)
911			for _, l := range inputs.LabelAdd {
912				found := false
913				for _, existing := range labels {
914					if existing == l {
915						found = true
916						break
917					}
918				}
919				if !found {
920					labels = append(labels, l)
921				}
922			}
923			for _, l := range inputs.LabelRemove {
924				for i, existing := range labels {
925					if existing == l {
926						labels = append(labels[:i], labels[i+1:]...)
927						break
928					}
929				}
930			}
931			req.Labels = &labels
932		}
933	
934		return req
935	}
