937	// parseTrailNumberArg parses an optional positional trail-number argument.
938	// It returns 0 when no argument is supplied; a supplied value must be a
939	// positive integer (the server keys single-trail endpoints by number).
940	func parseTrailNumberArg(args []string) (int, error) {
941		if len(args) == 0 {
942			return 0, nil
943		}
944		n, err := strconv.Atoi(args[0])
945		if err != nil || n <= 0 {
946			return 0, fmt.Errorf("invalid trail number %q: expected a positive integer (see 'entire trail list')", args[0])
947		}
948		return n, nil
949	}
