981	func runTrailDelete(cmd *cobra.Command, number int, branch string, force bool) error {
982		ctx := cmd.Context()
983		w := cmd.OutOrStdout()
984	
985		return runAuthenticatedDataAPI(ctx, cmd.ErrOrStderr(), trailInsecureHTTP(cmd), func(ctx context.Context, client *api.Client) error {
986			forge, owner, repo, err := resolveTrailRemote(ctx)
987			if err != nil {
988				return err
989			}
990	
991			// Resolve the target trail. An explicit number is authoritative (a
992			// lookup is best-effort, only to label the confirmation); otherwise the
993			// branch's trail supplies the number.
994			title := ""
995			if number == 0 {
996				if branch == "" {
997					branch, err = GetCurrentBranch(ctx)
998					if err != nil {
999						return fmt.Errorf("failed to determine current branch: %w", err)
1000					}
1001				}
1002				found, ferr := findTrailByBranch(ctx, client, forge, owner, repo, branch)
1003				if ferr != nil {
1004					return ferr
1005				}
1006				if found == nil {
1007					return fmt.Errorf("no trail found for branch %q", branch)
1008				}
1009				if found.Number <= 0 {
1010					return fmt.Errorf("trail for branch %q has no number yet; cannot delete", branch)
1011				}
1012				number = found.Number
1013				title = found.Title
1014			} else if found, ferr := findTrailByNumber(ctx, client, forge, owner, repo, number); ferr == nil && found != nil {
1015				title = found.Title
1016			}
1017	
1018			proceed, err := confirmTrailDeletion(ctx, w, number, title, force, interactive.CanPromptInteractively())
1019			if err != nil {
1020				return err
1021			}
1022			if !proceed {
1023				return nil
1024			}
1025	
1026			if err := deleteTrailByNumber(ctx, client, forge, owner, repo, number); err != nil {
1027				return err
1028			}
1029	
1030			fmt.Fprintf(w, "Deleted trail #%d\n", number)
1031			return nil
1032		})
1033	}
