1035	// deleteTrailByNumber deletes the trail with the given integer number and
1036	// verifies the server's {ok:true} signal. CheckResponse accepts any 2xx and the
1037	// body is otherwise unread, so a destructive delete must confirm ok before
1038	// reporting success (decoding also drains the body for connection reuse).
1039	func deleteTrailByNumber(ctx context.Context, client *api.Client, forge, owner, repo string, number int) error {
1040		resp, err := client.Delete(ctx, trailNumberPath(forge, owner, repo, number))
1041		if err != nil {
1042			return fmt.Errorf("failed to delete trail: %w", err)
1043		}
1044		defer resp.Body.Close()
1045		if err := checkTrailResponse(resp); err != nil {
1046			return err
1047		}
1048		var delResp api.TrailDeleteResponse
1049		if err := api.DecodeJSON(resp, &delResp); err != nil {
1050			return fmt.Errorf("failed to decode delete response: %w", err)
1051		}
1052		if !delResp.OK {
1053			return fmt.Errorf("trail API did not confirm deletion of trail #%d", number)
1054		}
1055		return nil
1056	}
1057	
1058	// confirmTrailDeletion decides whether a trail delete should proceed. With
1059	// force it proceeds silently. Otherwise it requires an interactive terminal:
1060	// when none is available it refuses (returns an error) rather than deleting
1061	// unprompted; when one is, it shows a confirmation form. canPrompt is passed in
1062	// (rather than queried) so the decision is unit-testable without a TTY.
1063	func confirmTrailDeletion(ctx context.Context, w io.Writer, number int, title string, force, canPrompt bool) (bool, error) {
1064		if force {
1065			return true, nil
1066		}
1067		if !canPrompt {
1068			return false, fmt.Errorf("refusing to delete trail #%d without confirmation; pass --force", number)
1069		}
1070		// huh opens the TTY during form startup regardless of context state, so
1071		// guard explicitly to honor an already-cancelled command context.
1072		if ctx.Err() != nil {
1073			return false, nil //nolint:nilerr // cancelled context is a clean skip, not an error
1074		}
1075		prompt := fmt.Sprintf("Delete trail #%d?", number)
1076		if title != "" {
1077			prompt = fmt.Sprintf("Delete trail #%d (%s)?", number, title)
1078		}
1079		confirmed := false
1080		form := NewAccessibleForm(
1081			huh.NewGroup(huh.NewConfirm().Title(prompt).Value(&confirmed)),
1082		)
1083		if err := form.RunWithContext(ctx); err != nil {
1084			// A user abort (Esc) or context cancel (Ctrl+C) is a clean cancel, not
1085			// an error — mirror confirmDoctorFix / uiform.PromptYN.
1086			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
1087				return false, nil
1088			}
1089			return false, fmt.Errorf("trail deletion prompt: %w", err)
1090		}
1091		if !confirmed {
1092			fmt.Fprintln(w, "Trail deletion cancelled.")
1093			return false, nil
1094		}
1095		return true, nil
1096	}
