1177	// findTrailByBranch looks up a trail by branch name via the list API.
1178	func findTrailBySelector(ctx context.Context, client *api.Client, forge, owner, repo, selector string) (*api.TrailResource, error) {
1179		selector = strings.TrimSpace(selector)
1180		if selector == "" {
1181			return nil, nil //nolint:nilnil // empty selector means not found for this helper
1182		}
1183		if n, ok := parseTrailNumberSelector(selector); ok {
1184			found, err := findTrailByNumber(ctx, client, forge, owner, repo, n)
1185			if err != nil || found != nil {
1186				return found, err
1187			}
1188		}
1189		return findTrail(ctx, client, forge, owner, repo, func(t api.TrailResource) bool {
1190			return t.ID == selector || t.Branch == selector
1191		})
1192	}
1193	
1194	func parseTrailNumberSelector(selector string) (int, bool) {
1195		n, err := strconv.Atoi(strings.TrimSpace(selector))
1196		if err != nil || n <= 0 {
1197			return 0, false
1198		}
1199		return n, true
1200	}
1201	
1202	func findTrailByBranch(ctx context.Context, client *api.Client, forge, owner, repo, branch string) (*api.TrailResource, error) {
1203		return findTrail(ctx, client, forge, owner, repo, func(t api.TrailResource) bool {
1204			return t.Branch == branch
1205		})
1206	}
1207	
1208	// findTrailByNumber looks up a trail by numeric identifier via the list API.
1209	func findTrailByNumber(ctx context.Context, client *api.Client, forge, owner, repo string, number int) (*api.TrailResource, error) {
1210		return findTrail(ctx, client, forge, owner, repo, func(t api.TrailResource) bool {
1211			return t.Number == number
1212		})
1213	}
1214	
1215	func findTrail(ctx context.Context, client *api.Client, forge, owner, repo string, match func(api.TrailResource) bool) (*api.TrailResource, error) {
1216		// The list endpoint paginates; walk bounded pages so branch/number/id lookups do
1217		// not silently miss older trails beyond the first server-max page.
1218		offset := 0
1219		previousPageSignature := ""
1220		for range trailFindMaxPages {
1221			resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo)+trailListQueryWithOffset(nil, "", trailListServerMaxLimit, offset))
1222			if err != nil {
1223				return nil, fmt.Errorf("list trails: %w", err)
1224			}
1225	
1226			var listResp api.TrailListResponse
1227			decodeErr := func() error {
1228				defer resp.Body.Close()
1229				if err := checkTrailResponse(resp); err != nil {
1230					return err
1231				}
1232				if err := api.DecodeJSON(resp, &listResp); err != nil {
1233					return fmt.Errorf("decode trail list: %w", err)
1234				}
1235				return nil
1236			}()
1237			if decodeErr != nil {
1238				return nil, decodeErr
1239			}
1240	
1241			for i := range listResp.Trails {
1242				if match(listResp.Trails[i]) {
1243					return &listResp.Trails[i], nil
1244				}
1245			}
1246	
1247			pageLen := len(listResp.Trails)
1248			if pageLen == 0 || pageLen < trailListServerMaxLimit {
1249				break
1250			}
1251			if listResp.Total == 0 {
1252				pageSignature := trailListPageSignature(listResp.Trails)
1253				if pageSignature != "" && pageSignature == previousPageSignature {
1254					break
1255				}
1256				previousPageSignature = pageSignature
1257			}
1258			offset += pageLen
1259			if listResp.Total > 0 && offset >= listResp.Total {
1260				break
1261			}
1262		}
1263		return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
1264	}
1265	
1266	func trailListPageSignature(trails []api.TrailResource) string {
1267		if len(trails) == 0 {
1268			return ""
1269		}
1270		first := trails[0]
1271		last := trails[len(trails)-1]
1272		return fmt.Sprintf("%s/%d/%s:%s/%d/%s", first.ID, first.Number, first.Branch, last.ID, last.Number, last.Branch)
1273	}
1274	
1275	// trailsBasePath returns the API path prefix for trails endpoints
1276	// (e.g., "/api/v1/trails/gh/org/repo").
1277	func trailsBasePath(forge, owner, repo string) string {
1278		return fmt.Sprintf("/api/v1/trails/%s/%s/%s", forge, owner, repo)
1279	}
1280	
1281	// trailNumberPath returns the single-trail API path keyed by integer trail
1282	// number (e.g. "/api/v1/trails/gh/acme/repo/575"). The server validates an
1283	// integer here and rejects the trail UUID, so callers must pass Number, not ID.
1284	func trailNumberPath(forge, owner, repo string, number int) string {
1285		return trailsBasePath(forge, owner, repo) + "/" + strconv.Itoa(number)
1286	}
1287	
1288	// resolveTrailRemote resolves the origin remote and ensures the forge is
1289	// known to the trails API. Without this guard, an unmapped host (e.g.
1290	// gitlab.com, or a misconfigured entire:// URL with no forge prefix)
1291	// produces a malformed `/api/v1/trails//owner/repo` path that the server
1292	// rejects with an opaque error instead of a clear "unsupported forge" one.
1293	func resolveTrailRemote(ctx context.Context) (forge, owner, repo string, err error) {
1294		forge, owner, repo, err = gitremote.ResolveRemoteRepo(ctx, "origin")
1295		if err != nil {
1296			return "", "", "", fmt.Errorf("failed to resolve repository: %w", err)
1297		}
1298		if forge == "" {
1299			return "", "", "", errors.New("origin remote is not on a forge supported by Entire trails (supported: github.com)")
1300		}
1301		return forge, owner, repo, nil
1302	}
1303	
1304	// checkTrailResponse checks the API response and returns user-friendly errors.
1305	// For auth failures, it appends a hint to re-authenticate while preserving the server's error message.
1306	func checkTrailResponse(resp *http.Response) error {
1307		if err := api.CheckResponse(resp); err != nil {
1308			if resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden {
1309				return fmt.Errorf("%w — run 'entire login' to re-authenticate", err)
1310			}
1311			return fmt.Errorf("trail API: %w", err)
1312		}
1313		return nil
1314	}
1315	
1316	// resolveCreateBranch picks the branch a non-interactive `trail create` targets.
1317	// An explicit --branch always wins. Otherwise, on a feature branch it uses the
1318	// checked-out branch; when the checked-out branch IS the base (the trail's
1319	// target/default branch) — or HEAD is detached — it derives a new branch from
1320	// the title when one was given (starting fresh work), else falls back to current.
1321	// Comparing against the already-resolved base keeps this consistent with how
1322	// `base` itself was detected (avoids a second, divergent default-branch lookup).
1323	func resolveCreateBranch(branchFlag, currentBranch, base, title string, titleProvided bool) string {
1324		if branchFlag != "" {
1325			return branchFlag
1326		}
1327		if titleProvided && (currentBranch == base || currentBranch == "") {
1328			return slugifyTitle(title)
1329		}
1330		return currentBranch
1331	}
1332	
1333	// slugifyTitle converts a title string into a branch-friendly slug.
1334	// Example: "Add user authentication" -> "add-user-authentication"
1335	func slugifyTitle(title string) string {
1336		s := strings.ToLower(strings.TrimSpace(title))
1337		// Replace spaces and underscores with hyphens
1338		s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
1339		// Remove anything that's not alphanumeric, hyphen, or slash
1340		var b strings.Builder
1341		prevHyphen := false
1342		for _, r := range s {
1343			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
1344				b.WriteRune(r)
1345				prevHyphen = false
1346			} else if r == '-' && !prevHyphen {
1347				b.WriteRune('-')
1348				prevHyphen = true
1349			}
1350		}
1351		return strings.Trim(b.String(), "-")
1352	}
1353	
1354	// branchNeedsCreation checks if a branch exists locally.
1355	func branchNeedsCreation(repo *git.Repository, branchName string) bool {
1356		_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
1357		return err != nil
1358	}
1359	
1360	// createBranch creates a new local branch pointing at HEAD without checking it out.
1361	func createBranch(repo *git.Repository, branchName string) error {
1362		head, err := repo.Head()
1363		if err != nil {
1364			return fmt.Errorf("failed to get HEAD: %w", err)
1365		}
1366		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
1367		if err := repo.Storer.SetReference(ref); err != nil {
1368			return fmt.Errorf("failed to create branch ref: %w", err)
1369		}
1370		return nil
1371	}
1372	
1373	func cleanupCreatedTrailBranch(repo *git.Repository, branchName string, localCreated, remotePushed bool, errW io.Writer) {
1374		localRemoved := !localCreated
1375		if localCreated {
1376			branchRef := plumbing.NewBranchReferenceName(branchName)
1377			if head, err := repo.Head(); err == nil && head.Name() == branchRef {
1378				fmt.Fprintf(errW, "Warning: not deleting local branch %s after trail creation failed because it is checked out; switch branches and run 'git branch -D %s' if you do not need it\n", branchName, branchName)
1379			} else if err := repo.Storer.RemoveReference(branchRef); err != nil {
1380				fmt.Fprintf(errW, "Warning: failed to delete local branch %s after trail creation failed: %v; run 'git branch -D %s' if you do not need it\n", branchName, err, branchName)
1381			} else {
1382				localRemoved = true
1383			}
1384		}
1385		if remotePushed {
1386			if !localRemoved {
1387				fmt.Fprintf(errW, "Warning: not deleting remote branch %s after trail creation failed because local cleanup did not complete; run 'git push origin --delete %s' if you do not need it\n", branchName, branchName)
1388				return
1389			}
1390			if err := deleteBranchFromOrigin(branchName); err != nil {
1391				fmt.Fprintf(errW, "Warning: failed to delete remote branch %s after trail creation failed: %v\n", branchName, err)
1392			}
1393		}
1394	}
1395	
1396	// pushBranchToOrigin pushes a branch to the origin remote.
1397	func pushBranchToOrigin(branchName string) error {
1398		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
1399		defer cancel()
1400		cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
1401		if output, err := cmd.CombinedOutput(); err != nil {
1402			return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
1403		}
1404		return nil
1405	}
1406	
1407	// branchExistsOnOrigin reports whether origin already has a branch with the
1408	// given name, so callers can avoid treating a pre-existing remote branch as one
1409	// they created.
1410	func branchExistsOnOrigin(branchName string) (bool, error) {
1411		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
1412		defer cancel()
1413		cmd := exec.CommandContext(ctx, "git", "ls-remote", "--heads", "origin", branchName)
1414		output, err := cmd.CombinedOutput()
1415		if err != nil {
1416			return false, fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
1417		}
1418		return strings.TrimSpace(string(output)) != "", nil
1419	}
1420	
1421	func deleteBranchFromOrigin(branchName string) error {
1422		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
1423		defer cancel()
1424		cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "origin", "--delete", branchName)
1425		if output, err := cmd.CombinedOutput(); err != nil {
1426			outputText := strings.TrimSpace(string(output))
1427			if strings.Contains(outputText, "remote ref does not exist") {
1428				return nil
1429			}
1430			return fmt.Errorf("%s: %w", outputText, err)
1431		}
1432		return nil
1433	}
