export async function fetchTrailChecks(
  org: string,
  repo: string,
  number: number,

// GET /:host/:owner/:repo/:number/mergeability — Get merge readiness
trailRoutes.get(
  "/:host/:owner/:repo/:number/mergeability",
  describeRoute({
    tags: ["Trails"],
    summary: "Get merge readiness for a trail",
    responses: {
      200: {
        description: "Trail mergeability",
        content: { "application/json": { schema: resolver(trailMergeabilitySchema) } },
      },
      404: {
        description: "Trail not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      409: {
        description: "Repository has no GitHub App installation",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      503: {
        description: "GitHub App token temporarily unavailable",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    // Use the installation token: mergeability is a read (checks + ahead/behind)
    // that doesn't act as the user, so a stale viewer token shouldn't break it.
    const ctx = await resolveTrailWithInstallationToken(c)
    if (ctx instanceof Response) return ctx
    const { repoFullName, trail: row, githubToken: token } = ctx

    try {
      if (!row.branch) {
        return c.json({
          approval_gate_passed: false,
          checks_passed: false,
          checks_status: "none",
          checks: [],
          behind_by: 0,
          comparison_status: "unknown",
